-- === YANGILIKLAR ===
-- #13 [MEDIUM] 2025-01-22  Tashkent International University Assumes the Chairmanship of TURKUNIB
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='0b2428c5-4912-4e2b-bc28-01ba252ea454.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='turkunib-activities'), 'TURKUNIB', 1, 1, '2025-01-22 09:00:00', '2025-01-22 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Tashkent International University Assumes the Chairmanship of TURKUNIB for 2025–2026', 'tashkent-international-university-assumes-the-chairmanship-of-turkunib-for-2025-2026', '<p>The chairmanship of the Turkic Universities Union (TURKUNIB) formally passed to Tashkent International University (TIU) for the 2025–2026 term at a handover ceremony held in Tashkent on 22 January 2025.</p>
<p>Professor Adalat Muradov, Rector of Azerbaijan State University of Economics (UNEC), which concluded its term at the head of the Union, presented a symbolic key to TIU Director Iskandar Yuldashev, marking the transfer of leadership. The ceremony was attended by OTS Deputy Secretary General Dr. Mirvokhid Azimov, Advisor to the Minister of Higher Education, Science and Innovation of Uzbekistan Bobur Rakhimov, and heads and representatives of TURKUNIB member universities.</p>
<p>Speakers emphasized the priorities of the new term: strengthening academic collaboration among member universities, expanding student and faculty exchanges, and developing the Orhun Exchange Programme as the Union''s principal mobility instrument. Dr. Azimov and Mr. Yuldashev signed a Road Map setting out the activities planned for the 2025–2026 chairmanship.</p>
<p>The handover set the course for what would become a landmark period in TURKUNIB''s development. Under the TIU chairmanship, the Union went on to host its 8th General Assembly in Tashkent in October 2025, admitting 62 new member universities, and to advance the establishment of a Permanent Secretariat and a dedicated fund for the Orhun Exchange Programme – initiatives that took institutional shape over the months that followed.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/6727046b-f766-4ce8-b9fd-843da383514a.jpg" alt="Tashkent International University Assumes the Chairmanship of TURKUNIB for 2025–2026" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/8b7c90b3-3b1c-4924-8ad5-8bc80b0e0d19.jpg" alt="Tashkent International University Assumes the Chairmanship of TURKUNIB for 2025–2026" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/tashkent-international-university-assumes-chairmanship-of-turkunib-for-2025-2026--1">Tashkent International University assumes Chairmanship of TURKUNIB for 2025-2026</a></em></p>', 'The chairmanship of the Turkic Universities Union (TURKUNIB) formally passed to Tashkent International University (TIU) for the 2025–2026 term at a handover ceremony held in Tashkent on 22 January 2025.', '2025-01-22 09:00:00', '2025-01-22 09:00:00');
-- #25 [LOW] 2025-04-28  Hungary and the Turkic States Convene Summit on Culture, Education and
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='fe59d078-d019-42c5-8445-844dac44cc30.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='international-cooperation'), 'TURKUNIB', 1, 1, '2025-04-28 09:00:00', '2025-04-28 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Hungary and the Turkic States Convene Summit on Culture, Education and Innovation in Budapest', 'hungary-and-the-turkic-states-convene-summit-on-culture-education-and-innovation-in-budapest', '<p>The Hungarian-Turkic Summit on Culture, Education and Innovation opened in Budapest on 28 April 2025, bringing together ministers and high-level officials from Hungary and the Turkic states around three fields central to the region''s long-term development.</p>
<p>Addressing the opening, OTS Secretary General Ambassador Kubanychbek Omuraliev emphasized Hungary''s role as an Observer of the Organization of Turkic States and highlighted the dynamic, multifaceted cooperation that has developed between Hungary and the Turkic states. He underlined the significance of convening ministers and senior officials specifically on culture, education and innovation – domains in which Hungary''s engagement with the Turkic world has been especially active, notably through the scholarship opportunities Hungarian institutions extend to students from the region.</p>
<p>The Budapest summit acquires added meaning in light of subsequent developments. At the 8th General Assembly of the Turkic Universities Union in Tashkent in October 2025, the Government of Hungary presented proposals for a joint Research, Development and Innovation Fund and for an enhanced Orhun Exchange Programme – initiatives consistent with the education-and-innovation agenda convened in Budapest months earlier.</p>
<p>For TURKUNIB and its member universities, Hungary''s sustained engagement widens the Union''s horizons: an observer state with strong European academic networks actively proposing instruments for research funding and student mobility strengthens the bridge between the Turkic higher education space and the wider European academic community.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/564b86a7-8c10-4f94-b4cc-98cae9c74515.jpg" alt="Hungary and the Turkic States Convene Summit on Culture, Education and Innovation in Budapest" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/hungarian-turkic-summit-on-culture-education-and-innovation-started-its-work-in-budapest">Hungarian-Turkic Summit on Culture, Education and Innovation started its work in Budapest</a></em></p>', 'The Hungarian-Turkic Summit on Culture, Education and Innovation opened in Budapest on 28 April 2025, bringing together ministers and high-level officials from Hungary and the Turkic states around three fields central to the region''s long-term development.', '2025-04-28 09:00:00', '2025-04-28 09:00:00');
-- #14 [MEDIUM] 2025-06-25  Institutionalization, Financing and Digitalization: OTS Workshop Exami
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='635b1f7f-1cc5-4695-ae7b-77f242c214ae.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='higher-education'), 'TURKUNIB', 1, 1, '2025-06-25 09:00:00', '2025-06-25 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Institutionalization, Financing and Digitalization: OTS Workshop Examines the Future of the Orhun Process and TURKUNIB', 'institutionalization-financing-and-digitalization-ots-workshop-examines-the-future-of-the-orhun-process-and-turkunib', '<p>The structural questions shaping the future of academic mobility in the Turkic world were the focus of a dedicated workshop on the Orhun Process and TURKUNIB, held on 25 June 2025 within the Second Turkic World Summer School hosted by Ibn Haldun University, with the participation of OTS Deputy Secretary General Dr. Mirvokhid Azimov.</p>
<p>The workshop addressed the key challenges confronting the Orhun Exchange Programme and the Turkic Universities Union as they scale up: regulatory alignment among different national higher education systems; the financial frameworks needed to sustain mobility at greater volume; the institutionalization of structures that have until now operated on a rotating, voluntary basis; and the digitalization of processes on which a modern exchange programme depends. Dr. Azimov also delivered an address to the Summer School''s participants.</p>
<p>In retrospect, the Istanbul workshop mapped the agenda that would dominate the year that followed. Regulatory alignment, financing, institutionalization and digitalization were precisely the questions taken up by the 8th TURKUNIB General Assembly in Tashkent in October 2025, endorsed at the level of Heads of State in the Gabala Declaration, and carried into implementation through the OTS''s recruitment of dedicated experts and the decisions of the 9th Meeting of the Ministers of Education in 2026.</p>
<p>For TURKUNIB member universities, the workshop illustrates how the Union''s reform agenda has been built – through sustained expert dialogue linking the OTS Secretariat, universities and young scholars – and signals the practical changes coming to the way inter-university mobility across the Turkic world is organized, funded and administered.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/72e32283-1ef5-4b15-92cb-960cc7c09505.jpg" alt="Institutionalization, Financing and Digitalization: OTS Workshop Examines the Future of the Orhun Process and TURKUNIB" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/ad2a3bb4-1b5a-4508-9917-34342537e65b.jpg" alt="Institutionalization, Financing and Digitalization: OTS Workshop Examines the Future of the Orhun Process and TURKUNIB" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/deputy-secretary-general-of-the-organization-of-turkic-states-participated-in-workshop-on-orhun-process-and-turkunib-at-the-second-turkic-world-summer-school">Deputy Secretary General of the OTS Participated in Workshop on Orhun Process and TURKUNIB at the Second Turkic World Summer School</a></em></p>', 'The structural questions shaping the future of academic mobility in the Turkic world were the focus of a dedicated workshop on the Orhun Process and TURKUNIB, held on 25 June 2025 within the Second Turkic World Summer School hosted by Ibn Haldun University, with the participation of OTS Deputy…', '2025-06-25 09:00:00', '2025-06-25 09:00:00');
-- #23 [MEDIUM] 2025-09-19  Manas University at Thirty: A Flagship of Joint Higher Education in th
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='312494f2-1571-482e-bded-99ab7de9f2ba.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='higher-education'), 'TURKUNIB', 1, 1, '2025-09-19 09:00:00', '2025-09-19 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Manas University at Thirty: A Flagship of Joint Higher Education in the Turkic World', 'manas-university-at-thirty-a-flagship-of-joint-higher-education-in-the-turkic-world', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev paid a working visit to Kyrgyz-Turkish Manas University on 19 September 2025 at the university''s invitation, joining the institution''s leadership as it marked thirty years since its foundation.</p>
<p>The Secretary General met Rector Prof. Dr. Alpaslan Ceylan, Deputy Rector Prof. Dr. Almaz Ibraev and members of the faculty, acknowledging the university''s accomplishments over three decades. The visit placed particular emphasis on expanding cooperation through the Turkic Universities Union (TURKUNIB), of which Manas University is a member. The Secretary General also gave an interview to the university''s television channel on the structure, tasks and objectives of the Organization of Turkic States, and was presented with the commemorative medal “30 Years of Manas University.”</p>
<p>Established jointly by the Kyrgyz Republic and Türkiye, Manas University stands among the earliest and most successful experiments in shared higher education in the Turkic world – a bi-national institution educating students from across the region decades before a Turkic World Higher Education Area became a formal policy objective.</p>
<p>As the Turkic states now work to institutionalize mobility, quality assurance and diploma recognition across their university systems, the experience accumulated by joint institutions such as Manas University is a valuable resource for the entire TURKUNIB membership – living proof that deeply integrated, cross-border higher education in the Turkic world can flourish.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/84f7a916-3c85-4a20-a31f-dc05c1ed1a6d.jpg" alt="Manas University at Thirty: A Flagship of Joint Higher Education in the Turkic World" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/4ad5efa4-c8c1-438f-8191-f4c30b659308.jpg" alt="Manas University at Thirty: A Flagship of Joint Higher Education in the Turkic World" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-secretary-general-of-the-ots-visited-manas-university-and-received-the-commemorative-medal-30-years-of-manas-university">The Secretary General of the OTS visited Manas University and received the commemorative medal “30 Years of Manas University”</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev paid a working visit to Kyrgyz-Turkish Manas University on 19 September 2025 at the university''s invitation, joining the institution''s leadership as it marked thirty years since its foundation.', '2025-09-19 09:00:00', '2025-09-19 09:00:00');
-- #3 [HIGH] 2025-10-07  Gabala Summit Places Higher Education at the Heart of the Turkic Agend
