INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Gabala Summit Places Higher Education at the Heart of the Turkic Agenda: Leaders Endorse Reorganized Orhun Programme and a Turkic World Higher Education Area', 'gabala-summit-places-higher-education-at-the-heart-of-the-turkic-agenda-leaders-endorse-reorganized-orhun-programme-and-a-turkic-world-higher-education-area', '<p>The 12th Summit of the Organization of Turkic States, held on 7 October 2025 in Gabala, Azerbaijan under the theme “Regional Peace and Security,” produced outcomes of direct and lasting importance for the higher education community of the Turkic world.</p>
<p>The Summit gathered the Presidents of Azerbaijan, Kazakhstan, Kyrgyzstan, Türkiye and Uzbekistan – Ilham Aliyev, Kassym-Jomart Tokayev, Sadyr Zhaparov, Recep Tayyip Erdoğan and Shavkat Mirziyoyev – together with Prime Minister of Hungary Viktor Orbán, National Leader of the Turkmen People Gurbanguly Berdimuhamedov, President of the Turkish Republic of Northern Cyprus Ersin Tatar, and OTS Secretary General Ambassador Kubanychbek Omuraliev. The leaders adopted the Gabala Declaration, established an “OTS+” format for engagement with external partners, and adopted a decision on the development of TURKSOY. Turkmenistan was welcomed as an Observer in the Turkic Academy and the Turkic Culture and Heritage Foundation, and the Chairmanship-in-Office passed from Kyrgyzstan to Azerbaijan.</p>
<p>For universities, the most significant element of the Summit lies in its education provisions. According to the OTS, the Gabala Declaration endorsed the reorganization of the Orhun Exchange Programme and the establishment of a Turkic World Higher Education Area – the two structural reforms around which TURKUNIB''s current agenda is built. The Secretary General noted that the Organization now coordinates multilateral cooperation in over forty sectors, “ranging from economic integration and security to education, innovation, and space.”</p>
<p>The Summit''s decisions were reflected almost immediately in practice: one week later, the 8th General Assembly of TURKUNIB in Tashkent admitted 62 new member universities and took forward the concept of a Permanent Secretariat and a funded Orhun Exchange Programme.</p>
<p>The Gabala Summit confirmed that higher education, science and innovation are no longer peripheral items on the Turkic cooperation agenda but central pillars of it – providing TURKUNIB and its member universities with a mandate at the highest political level to accelerate the construction of a common higher education space.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/a8309d3f-5e9f-4033-9c27-92ca5cc7fdc9.jpg" alt="Gabala Summit Places Higher Education at the Heart of the Turkic Agenda: Leaders Endorse Reorganized Orhun Programme and a Turkic World Higher Education Area" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/c22ddec9-3a15-48bb-9007-46246fe666c1.jpg" alt="Gabala Summit Places Higher Education at the Heart of the Turkic Agenda: Leaders Endorse Reorganized Orhun Programme and a Turkic World Higher Education Area" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-12th-summit-of-the-organization-of-turkic-states-convened-in-gabala-azerbaijan">The 12th Summit of the Organization of Turkic States Convened in Gabala, Azerbaijan</a></em></p>', 'The 12th Summit of the Organization of Turkic States, held on 7 October 2025 in Gabala, Azerbaijan under the theme “Regional Peace and Security,” produced outcomes of direct and lasting importance for the higher education community of the Turkic world.', '2025-10-07 09:00:00', '2025-10-07 09:00:00');
-- #2 [HIGH] 2025-10-15  TURKUNIB Grows to a Union of More Than 170 Universities: 8th General A
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='e70db4d4-7295-4e82-9b27-3adbc2876776.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='turkunib-activities'), 'TURKUNIB', 1, 1, '2025-10-15 09:00:00', '2025-10-15 09:00:00');
