INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'TURKUNIB Grows to a Union of More Than 170 Universities: 8th General Assembly in Tashkent Admits 62 New Members and Charts an Institutional Reform Agenda', 'turkunib-grows-to-a-union-of-more-than-170-universities-8th-general-assembly-in-tashkent-admits-62-new-members-and-charts-an-institutional-reform-agenda', '<p>The 8th General Assembly of the Turkic Universities Union (TURKUNIB) convened on 15 October 2025 in Tashkent, hosted by Tashkent International University (TIU) in its capacity as Chair University of the Union for 2025–2026. The Assembly brought together rectors, academics and representatives of more than seventy member universities from across the Turkic world.</p>
<p>The opening session was addressed by senior figures of the Turkic cooperation architecture and of the host country: Hilala Umarova, Deputy Head of the Presidential Administration of the Republic of Uzbekistan in charge of educational reform; Kongratbay Sharipov, Minister of Higher Education, Science and Innovation of Uzbekistan; OTS Secretary General Ambassador Kubanychbek Omuraliev; Shahin Mustafayev, President of the Turkic Academy; and Iskandar Yuldashev, Executive Director of TIU. Recalling that “education has always been a bridge connecting cultures,” the Secretary General underscored the Union''s rapid growth: TURKUNIB''s membership had reached 109 universities, with a further 62 institutions applying to join.</p>
<p>In its working session, chaired with the participation of OTS Deputy Secretary General Dr. Mirvokhid Azimov, the Assembly adopted a decision admitting all 62 applicant universities – bringing the Union past the 170-member mark – and considered a concept paper on establishing a Permanent TURKUNIB Secretariat together with a dedicated Programme Fund for the Orhun Exchange Programme. Delegates also examined proposals from Türkiye''s Council of Higher Education on strengthening the Union''s institutional framework, and proposals from the Government of Hungary on a joint Research, Development and Innovation Fund and an enhanced Orhun Exchange Programme.</p>
<p>The Assembly took place against a supportive political backdrop: according to the OTS, the Gabala Declaration adopted at the 12th OTS Summit one week earlier endorsed the reorganization of the Orhun Exchange Programme and the establishment of a Turkic World Higher Education Area, and the OTS announced that it will allocate one million US dollars to support the programme''s implementation and expansion.</p>
<p>The Tashkent General Assembly thus marked a turning point for TURKUNIB – the largest enlargement in its history combined with a concrete roadmap toward permanent institutions, secured funding for mobility, and a strengthened role at the centre of higher education cooperation in the Turkic world.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/52270a89-a433-468f-b683-d18c3909aa1c.jpg" alt="TURKUNIB Grows to a Union of More Than 170 Universities: 8th General Assembly in Tashkent Admits 62 New Members and Charts an Institutional Reform Agenda" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/85189322-ff38-4f5b-b013-e65f26cf0962.jpg" alt="TURKUNIB Grows to a Union of More Than 170 Universities: 8th General Assembly in Tashkent Admits 62 New Members and Charts an Institutional Reform Agenda" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/opening-of-the-8th-general-assembly-of-the-turkic-universities-union-convened-in-tashkent">Opening of the 8th General Assembly of the Turkic Universities Union convened in Tashkent</a></em></p>', 'The 8th General Assembly of the Turkic Universities Union (TURKUNIB) convened on 15 October 2025 in Tashkent, hosted by Tashkent International University (TIU) in its capacity as Chair University of the Union for 2025–2026. The Assembly brought together rectors, academics and representatives of…', '2025-10-15 09:00:00', '2025-10-15 09:00:00');
-- #19 [MEDIUM] 2025-10-17  Youth and Sports Ministers of the Turkic States Meet in Tashkent, Set 
