INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Youth and Sports Ministers of the Turkic States Meet in Tashkent, Set Course for 2026', 'youth-and-sports-ministers-of-the-turkic-states-meet-in-tashkent-set-course-for-2026', '<p>The 9th Meeting of the Ministers in Charge of Youth and Sports of the Organization of Turkic States convened in Tashkent on 17 October 2025, two days after the same city hosted the 8th General Assembly of the Turkic Universities Union – making it a week in which both the university and youth agendas of the Turkic world converged on the Uzbek capital.</p>
<p>The meeting was attended by Minister of Sports of Uzbekistan Adkham Ikramov and First Deputy Director of Uzbekistan''s Agency for Youth Affairs Dilnozaxon Kattaxonova, together with Minister of Youth and Sports of Azerbaijan Farid Gayibov, Minister of Tourism and Sport of Kazakhstan Yerbol Myrzabossynov, Director of the State Agency of Physical Culture and Sports of the Kyrgyz Republic Kazybek Moldazhiyev, Minister of Youth and Sports of Türkiye Osman Aşkın Bak, OTS Secretary General Ambassador Kubanychbek Omuraliev, and further senior officials from the member and observer states.</p>
<p>Ministers reviewed the youth and sports activities organized under the OTS umbrella during 2025 and discussed concrete projects to promote unity and solidarity among the young people of the Turkic states. The Kyrgyz delegation announced that the 10th Meeting will be held within the framework of the 6th World Nomad Games, scheduled for 31 August – 6 September 2026 in the Kyrgyz Republic.</p>
<p>Youth policy and higher education are closely intertwined: students form a substantial share of the young people these programmes serve, and university campuses are frequent venues for their implementation. The ministerial''s outcomes are therefore of practical interest to TURKUNIB member universities engaged in student life, sport and youth development across the Turkic world.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/d4547791-2c8e-4ff3-854f-a62fc296a05d.jpg" alt="Youth and Sports Ministers of the Turkic States Meet in Tashkent, Set Course for 2026" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/eda01c22-29b2-4358-aa3d-fbbada3384a8.jpg" alt="Youth and Sports Ministers of the Turkic States Meet in Tashkent, Set Course for 2026" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-9th-meeting-of-the-ministers-in-charge-of-youth-and-sports-of-the-ots-convened-in-tashkent">The 9th Meeting of the Ministers in Charge of Youth and Sports of the OTS convened in Tashkent</a></em></p>', 'The 9th Meeting of the Ministers in Charge of Youth and Sports of the Organization of Turkic States convened in Tashkent on 17 October 2025, two days after the same city hosted the 8th General Assembly of the Turkic Universities Union – making it a week in which both the university and youth…', '2025-10-17 09:00:00', '2025-10-17 09:00:00');
-- #7 [HIGH] 2025-10-24  Turkic States Adopt Joint Declaration on Science, Technology and Innov
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='9af286f5-9322-4521-a3f8-4fe48259e23e.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2025-10-24 09:00:00', '2025-10-24 09:00:00');
