INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic States Adopt Joint Declaration on Science, Technology and Innovation Cooperation in Baku', 'turkic-states-adopt-joint-declaration-on-science-technology-and-innovation-cooperation-in-baku', '<p>The 2nd Ministerial Meeting on Industry, Science, Technology and Innovation of the Organization of Turkic States convened in Baku on 24 October 2025 under the theme “From Strategic Partnership to Technological Integration of the Turkic States.”</p>
<p>Chaired by Minister of Economy of Azerbaijan Mikayil Jabbarov, the meeting brought together Minister of Economy and Commerce of the Kyrgyz Republic Bakyt Sydykov, Minister of Industry and Technology of Türkiye Mehmet Fatih Kacır, Vice-Minister of Industry and Construction of Kazakhstan Rakhymzhan Issakulov, Acting Director of Uzbekistan''s Agency for Innovative Development under the Ministry of Higher Education, Science and Innovations Asror Norov, Ambassador of Hungary to Azerbaijan Tamàs Torma, and OTS Secretary General Ambassador Kubanychbek Omuraliev.</p>
<p>The ministers focused on strengthening cooperation in industry, science, technology and innovation as the foundation of a competitive, knowledge-based and sustainable economic area across the Turkic world. The meeting adopted the Joint Declaration of the 2nd Ministerial Meeting, committing the states to deeper industrial and technological integration, together with an updated Action Plan for 2025–2026 covering the priority areas of cooperation. Kazakhstan will host the 3rd Ministerial Meeting in 2026.</p>
<p>The presence of Uzbekistan''s innovation agency – operating under the Ministry of Higher Education, Science and Innovation – illustrates how closely this agenda is tied to the university sector: research, technology development and innovation increasingly move through higher education institutions and their partnerships with industry.</p>
<p>For TURKUNIB and its member universities, the Baku Declaration and its accompanying Action Plan define the intergovernmental framework within which joint research programmes, technology transfer and university–industry cooperation across the Turkic states can develop, and signal growing opportunities for universities to contribute to the region''s technological integration.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/b012d1a4-1d0f-49c0-b69f-64ce8defa395.jpg" alt="Turkic States Adopt Joint Declaration on Science, Technology and Innovation Cooperation in Baku" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/7490ba45-24eb-465f-8cac-8daa7dda4462.jpg" alt="Turkic States Adopt Joint Declaration on Science, Technology and Innovation Cooperation in Baku" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-2nd-ministerial-meeting-on-industry-science-technology-and-innovation-of-the-ots-convenedin-baku">The 2nd Ministerial Meeting on Industry, Science, Technology and Innovation of the OTS convened in Baku</a></em></p>', 'The 2nd Ministerial Meeting on Industry, Science, Technology and Innovation of the Organization of Turkic States convened in Baku on 24 October 2025 under the theme “From Strategic Partnership to Technological Integration of the Turkic States.”', '2025-10-24 09:00:00', '2025-10-24 09:00:00');
-- #6 [HIGH] 2025-11-13  OTS Secretary General Visits Tashkent International University: New TU
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='67b2cb27-ebab-403f-b48c-452298fc6f79.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='turkunib-activities'), 'TURKUNIB', 1, 1, '2025-11-13 09:00:00', '2025-11-13 09:00:00');
