INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'OTS Secretary General Visits Tashkent International University: New TURKUNIB Website Presented', 'ots-secretary-general-visits-tashkent-international-university-new-turkunib-website-presented', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev visited Tashkent International University (TIU) on 13 November 2025, holding talks with TIU Rector Iskandar Yuldashev on the university''s chairmanship of the Turkic Universities Union (TURKUNIB) for 2025–2026 and on strengthening academic cooperation among the universities of the Turkic states.</p>
<p>The visit came one month after TIU hosted the 8th General Assembly of TURKUNIB in Tashkent – the largest gathering in the Union''s history, at which 62 new member universities were admitted. The discussions in Tashkent focused on carrying forward the Assembly''s outcomes during the Uzbek chairmanship, from the enlargement of the Union to the institutional reforms surrounding the Orhun Exchange Programme.</p>
<p>A highlight of the visit was the presentation of a new TURKUNIB website, developed under the TIU chairmanship, with its launch planned for the near future. The new digital platform is intended to serve the enlarged Union as a central source of information on its activities, member universities, mobility opportunities and cooperation initiatives – an increasingly important function as TURKUNIB grows into a network of more than 170 institutions spanning the Turkic world.</p>
<p>The Secretary General''s visit underlined the OTS''s close engagement with the Chair University and its support for TURKUNIB''s development as the principal platform of inter-university cooperation among the Turkic states. For member universities, the modernization of the Union''s communications infrastructure promises easier access to information on exchanges, joint projects and Union governance during a period of rapid growth.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/6fdab1b9-86ed-42b3-80db-1a10b53bf1c7.jpg" alt="OTS Secretary General Visits Tashkent International University: New TURKUNIB Website Presented" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/b35e329d-4a91-4639-9d73-b17dfc375413.jpg" alt="OTS Secretary General Visits Tashkent International University: New TURKUNIB Website Presented" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-visited-tashkent-international-university">OTS Secretary General visited Tashkent International University</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev visited Tashkent International University (TIU) on 13 November 2025, holding talks with TIU Rector Iskandar Yuldashev on the university''s chairmanship of the Turkic Universities Union (TURKUNIB) for 2025–2026 and on strengthening academic…', '2025-11-13 09:00:00', '2025-11-13 09:00:00');
-- #22 [MEDIUM] 2025-11-13  Oriental Studies and the Orhun Programme: OTS Secretary General Visits
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='c421e301-2a7a-4b80-a7a6-7f28aec25d5f.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='higher-education'), 'TURKUNIB', 1, 1, '2025-11-13 09:00:00', '2025-11-13 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Oriental Studies and the Orhun Programme: OTS Secretary General Visits Tashkent State University of Oriental Studies', 'oriental-studies-and-the-orhun-programme-ots-secretary-general-visits-tashkent-state-university-of-oriental-studies', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev visited Tashkent State University of Oriental Studies (TSUOS) on 13 November 2025, meeting Rector Gulchehra Rixsiyeva to discuss the expansion of educational cooperation and academic partnerships among the Turkic countries.</p>
<p>The two sides agreed to strengthen collaboration and increase joint initiatives through the Orhun Exchange Programme of the Turkic Universities Union – a concrete, university-level commitment to the mobility instrument at the heart of TURKUNIB''s agenda. During the visit, the Secretary General also delivered a lecture entitled “Current State and Prospects for the Development of Cooperation within the Framework of the OTS,” emphasizing to students and faculty the role of educational and cultural cooperation in deepening ties among the member states.</p>
<p>The visit continued an engagement begun earlier in the year, when the TSUOS leadership visited OTS Headquarters in Istanbul in April 2025, and formed part of a series of university visits by the Secretary General in Tashkent that week, including Tashkent International University – TURKUNIB''s Chair University – and Nordic International University, one of the Union''s newest members.</p>
<p>Agreements of this kind show the Orhun Exchange Programme working as intended: not an abstract framework, but a channel through which individual universities commit to concrete joint activity. For the wider TURKUNIB membership, TSUOS''s engagement illustrates how universities can anchor their internationalization strategies in the Union''s common mobility architecture.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/12568018-61ed-4def-b963-51052732c168.jpg" alt="Oriental Studies and the Orhun Programme: OTS Secretary General Visits Tashkent State University of Oriental Studies" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/018deee7-a7c3-419f-80de-a92a577c0c9f.jpg" alt="Oriental Studies and the Orhun Programme: OTS Secretary General Visits Tashkent State University of Oriental Studies" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-visited-tashkent-state-university-of-oriental-studies">OTS Secretary General visited Tashkent State University of Oriental Studies</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev visited Tashkent State University of Oriental Studies (TSUOS) on 13 November 2025, meeting Rector Gulchehra Rixsiyeva to discuss the expansion of educational cooperation and academic partnerships among the Turkic countries.', '2025-11-13 09:00:00', '2025-11-13 09:00:00');
-- #28 [LOW] 2025-11-15  New TURKUNIB Member in Focus: OTS Secretary General Visits Nordic Inte
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='61d3c172-af15-47fd-8695-9e18c3738e81.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='turkunib-activities'), 'TURKUNIB', 1, 1, '2025-11-15 09:00:00', '2025-11-15 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'New TURKUNIB Member in Focus: OTS Secretary General Visits Nordic International University in Tashkent', 'new-turkunib-member-in-focus-ots-secretary-general-visits-nordic-international-university-in-tashkent', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev visited Nordic International University (NIU) in Tashkent on 15 November 2025, at the initiative of the university''s leadership, meeting Chairman of the Supervisory Board Alisher Jurayev and Rector Dr. Sherzod Mustafaqulov.</p>
<p>The Secretary General congratulated NIU on its admission to the Turkic Universities Union – the university joined TURKUNIB during the 8th General Assembly held in Tashkent on 15 October 2025, one of the 62 institutions admitted in the Union''s largest-ever enlargement. He encouraged the university to cooperate closely with Tashkent International University, which holds the TURKUNIB chairmanship for 2025–2026.</p>
<p>The two sides discussed expanding educational cooperation and agreed to implement joint projects within the framework of TURKUNIB''s Orhun Exchange Programme. The university''s leadership also presented several of NIU''s ongoing projects to the Secretary General.</p>
<p>The visit illustrates what TURKUNIB''s enlargement means in practice: within a month of admission, a new member university was engaging directly with the OTS leadership and committing to joint activity under the Union''s mobility programme. For the dozens of institutions that joined TURKUNIB in 2025, NIU''s early engagement offers a template for translating membership into concrete cooperation.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/ce8a9f0c-edbf-4247-be49-4b74c0c7850c.jpg" alt="New TURKUNIB Member in Focus: OTS Secretary General Visits Nordic International University in Tashkent" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/c221d41b-b93f-4e98-9718-0fd2aea56fd4.jpg" alt="New TURKUNIB Member in Focus: OTS Secretary General Visits Nordic International University in Tashkent" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-visited-nordic-international-university">OTS Secretary General visited Nordic International University</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev visited Nordic International University (NIU) in Tashkent on 15 November 2025, at the initiative of the university''s leadership, meeting Chairman of the Supervisory Board Alisher Jurayev and Rector Dr. Sherzod Mustafaqulov.', '2025-11-15 09:00:00', '2025-11-15 09:00:00');
-- #20 [MEDIUM] 2025-11-18  Turkic Academy Marks Fifteen Years of Advancing Shared Scholarship
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='6e571848-c95c-4655-b962-8c52b9f49611.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2025-11-18 09:00:00', '2025-11-18 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic Academy Marks Fifteen Years of Advancing Shared Scholarship', 'turkic-academy-marks-fifteen-years-of-advancing-shared-scholarship', '<p>The Turkic Academy celebrated its fifteenth anniversary at a ceremony held in Ankara on 18 November 2025, attended by OTS Deputy Secretary General Merey Mukazhan alongside representatives of the sister institutions of the Turkic cooperation family, including TÜRKSOY, TURKPA, the Turkic Culture and Heritage Foundation, the Turkic Investment Fund and the Turkic Chamber of Commerce and Industry.</p>
<p>The programme combined protocol remarks with a presentation, a panel session and an exhibition dedicated to the Academy''s work. In his address, Deputy Secretary General Mukazhan highlighted the Academy''s fifteen years of advancing research on the shared history, language and cultural heritage of the Turkic world, and emphasized education and scientific cooperation as core elements of the “Turkic World Vision-2040.” He also welcomed the adoption of the Common Turkic Alphabet as a development strengthening mutual understanding and cultural unity across the region.</p>
<p>Since its establishment, the Turkic Academy has grown into the principal scientific institution of the Turkic cooperation framework – coordinating joint research projects, publications and scholarly gatherings that draw on the expertise of universities throughout the member states, from the “Common History of Turkic Countries” project to the centenary conference on Turkology co-organized with Al-Farabi Kazakh National University in 2026.</p>
<p>For TURKUNIB member universities, the Academy is a natural institutional partner: its research agenda in history, linguistics and heritage runs through university departments across the Turkic world, and its anniversary is a reminder of how far the region''s shared scientific infrastructure has developed in a decade and a half.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/9aaaf1fa-4a63-4705-98da-7f7d70418937.jpg" alt="Turkic Academy Marks Fifteen Years of Advancing Shared Scholarship" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/deputy-secretary-general-of-the-organization-of-turkic-states-attended-the-15th-anniversary-ceremony-of-the-turkic-academy-">Deputy Secretary General of the Organization of Turkic States attended the 15th Anniversary Ceremony of the Turkic Academy</a></em></p>', 'The Turkic Academy celebrated its fifteenth anniversary at a ceremony held in Ankara on 18 November 2025, attended by OTS Deputy Secretary General Merey Mukazhan alongside representatives of the sister institutions of the Turkic cooperation family, including TÜRKSOY, TURKPA, the Turkic Culture…', '2025-11-18 09:00:00', '2025-11-18 09:00:00');
-- #21 [MEDIUM] 2025-12-15  Tashkent Forum Celebrates UNESCO's Proclamation of World Turkic Langua
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='bf0fca96-f38e-4b54-b985-2745eb5b3665.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='youth-student-affairs'), 'TURKUNIB', 1, 1, '2025-12-15 09:00:00', '2025-12-15 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Tashkent Forum Celebrates UNESCO''s Proclamation of World Turkic Language Family Day', 'tashkent-forum-celebrates-unescos-proclamation-of-world-turkic-language-family-day', '<p>The Turkic World Youth Education Forum, dedicated to the first observance of World Turkic Language Family Day, was held in Tashkent on 15 December 2025, organized by the International Turkic States University. More than 150 participants – government representatives, academics, think-tank experts, diplomats and young people – took part.</p>
<p>The forum marked a historic milestone: the official proclamation of 15 December as World Turkic Language Family Day at the 43rd session of the UNESCO General Conference in November 2025, an international recognition of the linguistic and cultural heritage shared by the Turkic peoples.</p>
<p>Discussions unfolded in two panel sessions: “Sustainable Development and Strategic Cooperation of the Turkic States in a Changing Geopolitical Environment” and “Toward Turkic Cultural Identity and a Common Spiritual Space: The Role of Turkic World Youth in the Process of Integration.” Addressing the forum, OTS Deputy Secretary General Dr. Mirvokhid Azimov emphasized education and youth as a top priority within the OTS''s more than thirty areas of cooperation, and recalled the Charter of the Turkic World adopted at the 2024 Bishkek Summit.</p>
<p>That a university convened the forum is itself telling: higher education institutions are increasingly the venues where the Turkic world''s cultural, linguistic and youth agendas meet. For TURKUNIB member universities – many of which teach and research Turkic languages – the UNESCO recognition offers an annual occasion to showcase their scholarship and connect their students to a shared regional heritage.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/f29c055e-b520-4d88-81c8-80af61c16485.jpg" alt="Tashkent Forum Celebrates UNESCO&#x27;s Proclamation of World Turkic Language Family Day" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/81771d0c-efff-4f82-8e8e-de22c420577c.jpg" alt="Tashkent Forum Celebrates UNESCO&#x27;s Proclamation of World Turkic Language Family Day" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-turkic-world-youth-education-forum-dedicated-to-world-turkic-language-family-day-held-in-tashkent">The Turkic World Youth Education Forum dedicated to World Turkic Language Family Day held in Tashkent</a></em></p>', 'The Turkic World Youth Education Forum, dedicated to the first observance of World Turkic Language Family Day, was held in Tashkent on 15 December 2025, organized by the International Turkic States University. More than 150 participants – government representatives, academics, think-tank…', '2025-12-15 09:00:00', '2025-12-15 09:00:00');
-- #29 [LOW] 2025-12-20  From the Turkic World to Silicon Valley: OTS Deepens Innovation-Ecosys
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='07f554c4-d64e-47e5-aeec-7e1c316855a0.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='innovation-technology'), 'TURKUNIB', 1, 1, '2025-12-20 09:00:00', '2025-12-20 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'From the Turkic World to Silicon Valley: OTS Deepens Innovation-Ecosystem Ties with Silk Road Innovation Hub', 'from-the-turkic-world-to-silicon-valley-ots-deepens-innovation-ecosystem-ties-with-silk-road-innovation-hub', '<p>During a visit to the United States, OTS Secretary General Ambassador Kubanychbek Omuraliev visited the Silk Road Innovation Hub in California on 20 December 2025, meeting its Founder and Chief Executive Officer Aset Abdualiyev.</p>
<p>The Secretary General was briefed on the Hub''s activities – startup acceleration, innovation support and ecosystem building connecting entrepreneurs from Central Asia and the wider region with Silicon Valley – as well as its medium- and long-term development strategies. The visit built on an existing relationship: in July 2025, the OTS Secretariat and the Silk Road Innovation Hub had launched joint startup initiatives aimed at supporting entrepreneurs from the Turkic states.</p>
<p>The Organization''s cultivation of ties with one of the world''s leading innovation ecosystems reflects a broader ambition running through the Turkic cooperation agenda – visible equally in the Baku ministerial on science, technology and innovation, the AI theme of the 2026 Turkistan Summit, and the joint satellite programme: connecting the region''s emerging technology sector to global networks of capital, expertise and markets.</p>
<p>Universities are foundational to that ambition. Student startups, university incubators and technology transfer offices are where much of the Turkic world''s entrepreneurial talent first takes shape, and bridges to Silicon Valley of the kind the OTS is building expand the horizons available to the innovators emerging from TURKUNIB member universities.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/e7a99db7-eee6-4f5a-a0d6-27b426cb497a.jpg" alt="From the Turkic World to Silicon Valley: OTS Deepens Innovation-Ecosystem Ties with Silk Road Innovation Hub" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-visited-silk-road-innovation-hub-in-california">OTS Secretary General visited Silk Road Innovation Hub in California</a></em></p>', 'During a visit to the United States, OTS Secretary General Ambassador Kubanychbek Omuraliev visited the Silk Road Innovation Hub in California on 20 December 2025, meeting its Founder and Chief Executive Officer Aset Abdualiyev.', '2025-12-20 09:00:00', '2025-12-20 09:00:00');
-- #5 [HIGH] 2026-01-23  OTS Moves to Strengthen the Institutional Foundations of the Orhun Exc
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='16a4b807-bc45-497c-943b-2ec747726579.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='turkunib-activities'), 'TURKUNIB', 1, 1, '2026-01-23 09:00:00', '2026-01-23 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'OTS Moves to Strengthen the Institutional Foundations of the Orhun Exchange Programme and TURKUNIB', 'ots-moves-to-strengthen-the-institutional-foundations-of-the-orhun-exchange-programme-and-turkunib', '<p>In January 2026, the Organization of Turkic States took a concrete step toward the professionalization of the Turkic world''s flagship academic mobility architecture, announcing the recruitment of dedicated experts for the institutional development of the Orhun Exchange Programme and the Turkic Universities Union (TURKUNIB).</p>
<p>Under the call published on 23 January 2026, the OTS Secretariat sought two consultants to be based at its headquarters in Istanbul: a Legal and Institutional Framework Expert and a Higher Education Mobility Expert. The positions were established for nine-month terms, extendable in line with performance and organizational needs, with applications accepted until 5 February 2026 and detailed qualification requirements set out in dedicated terms of reference.</p>
<p>The significance of this announcement goes beyond staffing. The mandates of the two experts – legal and institutional frameworks on the one hand, and higher education mobility on the other – correspond precisely to the reform agenda that emerged from the 8th TURKUNIB General Assembly in Tashkent in October 2025 and from the Gabala Summit''s endorsement of a reorganized Orhun Exchange Programme and a Turkic World Higher Education Area. By building expert capacity within its Secretariat, the OTS laid the groundwork for the decisions subsequently taken by the 9th Meeting of the Ministers of Education in June 2026, including the establishment of a Permanent TURKUNIB Secretariat and a Dedicated Programme Fund for the Orhun Exchange Programme.</p>
<p>For TURKUNIB member universities, this development signals that the mobility and institutional reforms discussed in recent assemblies are moving from concept to implementation – with professional legal, institutional and mobility expertise now dedicated to designing the systems through which students and staff of Turkic world universities will study, teach and conduct research across borders.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-call-for-qualified-experts-for-the-institutional-development-of-the-orhun-exchange-program-and-turkunib">OTS Call for Qualified Experts for the Institutional Development of the Orhun Exchange Program and TURKUNIB</a></em></p>', 'In January 2026, the Organization of Turkic States took a concrete step toward the professionalization of the Turkic world''s flagship academic mobility architecture, announcing the recruitment of dedicated experts for the institutional development of the Orhun Exchange Programme and the Turkic…', '2026-01-23 09:00:00', '2026-01-23 09:00:00');
-- #11 [MEDIUM] 2026-03-27  Turkic States Plan Joint Hackathons and Competitions to Engage Youth i
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='55a7fc08-cba0-41b1-ac9b-24a94fd9cf5f.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='innovation-technology'), 'TURKUNIB', 1, 1, '2026-03-27 09:00:00', '2026-03-27 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic States Plan Joint Hackathons and Competitions to Engage Youth in Artificial Intelligence and Digital Development', 'turkic-states-plan-joint-hackathons-and-competitions-to-engage-youth-in-artificial-intelligence-and-digital-development', '<p>Senior information and communication technology officials of the Turkic states gathered in Shymkent, Kazakhstan, on 27 March 2026 for a panel session on “Artificial Intelligence and Digital Development: Enhancing Cooperation among the OTS States,” convened with the participation of OTS Deputy Secretary General Dr. Mirvokhid Azimov and private-sector representatives from across the region.</p>
<p>Participants examined artificial intelligence and digital development as essential drivers of transformation across industries, governance, education, healthcare and commerce – an explicit recognition that the digital agenda now reaches into every classroom and laboratory of the Turkic world. Discussions emphasized strengthening digital connectivity and data exchange among the member states, and the particular importance of engaging young people and professionals in the digital transformation now under way.</p>
<p>As a practical outcome, participants committed to organizing joint hackathons, competitions, forums and other hands-on engagements across the Turkic states – formats designed to bring together young talent from different countries around shared technological challenges.</p>
<p>The Shymkent commitments, which preceded the Turkistan Informal Summit''s adoption of artificial intelligence and digital development as its central theme in May 2026, are of direct interest to universities and their students. Joint hackathons and competitions offer students and young researchers of the Turkic world opportunities to collaborate across borders, test their skills and build professional networks – objectives that align closely with TURKUNIB''s mission of connecting the academic communities of its member universities.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/046a4404-ddd0-471d-9b38-5a9386ebfaaa.jpg" alt="Turkic States Plan Joint Hackathons and Competitions to Engage Youth in Artificial Intelligence and Digital Development" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/d3447a11-3f68-4ded-97db-5bbc6fb9113b.jpg" alt="Turkic States Plan Joint Hackathons and Competitions to Engage Youth in Artificial Intelligence and Digital Development" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/panel-session-on-artificial-intelligence-and-digital-development--enhancing-cooperation-among-the-ots-states-convened-in-shymkent-kazakhstan">Panel Session on “Artificial Intelligence and Digital Development: Enhancing Cooperation among the OTS States” convened in Shymkent, Kazakhstan</a></em></p>', 'Senior information and communication technology officials of the Turkic states gathered in Shymkent, Kazakhstan, on 27 March 2026 for a panel session on “Artificial Intelligence and Digital Development: Enhancing Cooperation among the OTS States,” convened with the participation of OTS Deputy…', '2026-03-27 09:00:00', '2026-03-27 09:00:00');
-- #8 [HIGH] 2026-03-30  Turkic World Space Cooperation Advances in Tashkent: Joint Satellite N
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='ac16ca7b-0522-4e68-b234-c00d7a1f4e4c.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2026-03-30 09:00:00', '2026-03-30 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic World Space Cooperation Advances in Tashkent: Joint Satellite Nears Launch as Education and Capacity-Building Take Centre Stage', 'turkic-world-space-cooperation-advances-in-tashkent-joint-satellite-nears-launch-as-education-and-capacity-building-take-centre-stage', '<p>The 5th Meeting of the Heads of Space Agencies of the Organization of Turkic States, held in Tashkent on 30 March 2026 with the participation of OTS Secretary General Ambassador Kubanychbek Omuraliev, confirmed that space has become one of the most dynamic areas of scientific and technological cooperation in the Turkic world – with education at its core.</p>
<p>The meeting reviewed manufacturing progress and launch preparations for the 12U OTS-SAT Cube Satellite, the flagship joint innovation project of the Turkic states. Days later, the OTS announced that the nanosatellite – designed to support Earth observation, in-orbit technology demonstration and the development of joint space capabilities – had reached its final manufacturing stage and was approaching launch. Participants also worked to finalize the draft Space Industrial Agreement for Capacity Development of Collaboration within the OTS.</p>
<p>Significantly for the academic community, the agenda devoted particular attention to cooperation in education and capacity-building. The heads of agencies discussed the development of the Turkic Space Explorers Academy, which already engages more than 170 students from across the member states, as well as the organization of “Turkic World Space Days” at international events. “Cooperation in the space area has become an important pillar of integration within the Turkic World,” the Secretary General stated.</p>
<p>The Turkic world''s first joint satellite is more than an engineering milestone: it is a demonstration that the region''s states can pool scientific talent, industrial capacity and research infrastructure around a shared high-technology goal. For TURKUNIB member universities – particularly their engineering, physics and information technology faculties – the expanding space agenda opens avenues for joint research, student engagement in real missions, and participation in the capacity-building programmes now being institutionalized across the Turkic states.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/e54feb9e-e5f6-4a89-b0ad-0f7b1f98a2fe.jpg" alt="Turkic World Space Cooperation Advances in Tashkent: Joint Satellite Nears Launch as Education and Capacity-Building Take Centre Stage" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/f9916a68-f78e-41c2-b74f-c180eb27c04a.jpg" alt="Turkic World Space Cooperation Advances in Tashkent: Joint Satellite Nears Launch as Education and Capacity-Building Take Centre Stage" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/5th-meeting-of-the-heads-of-space-agencies-of-the-ots-held-in-tashkent">5th Meeting of the Heads of Space Agencies of the OTS held in Tashkent</a></em></p>', 'The 5th Meeting of the Heads of Space Agencies of the Organization of Turkic States, held in Tashkent on 30 March 2026 with the participation of OTS Secretary General Ambassador Kubanychbek Omuraliev, confirmed that space has become one of the most dynamic areas of scientific and technological…', '2026-03-30 09:00:00', '2026-03-30 09:00:00');
-- #12 [MEDIUM] 2026-03-31  Space Technologies Highlighted as a Driver of Scientific Progress at T
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='59412353-c712-460c-a6b8-0727fa4dfb58.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2026-03-31 09:00:00', '2026-03-31 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Space Technologies Highlighted as a Driver of Scientific Progress at Tashkent Conference', 'space-technologies-highlighted-as-a-driver-of-scientific-progress-at-tashkent-conference', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev addressed the Space Technology Conference 2026 in Tashkent on 31 March 2026, the day after the 5th Meeting of the Heads of Space Agencies of the Turkic states convened in the same city. The conference gathered experts, policymakers, industry representatives and international organizations around the rapidly developing space agenda.</p>
<p>In his address, the Secretary General emphasized space technologies as a driver of economic growth, scientific progress and sustainable development, and highlighted the role of the Organization of Turkic States in fostering regional cooperation in this field. He pointed to the 12U OTS-SAT Cube Satellite Project – the joint nanosatellite of the Turkic states, then approaching launch – as tangible evidence of what the region can develop together, and described a widening collaboration agenda spanning satellite development, education, capacity-building and the promotion of innovation ecosystems.</p>
<p>The framing is significant for the higher education community: space cooperation among the Turkic states is being built deliberately around education and capacity-building, not only around hardware. Universities supply the engineers, physicists and data scientists on whom the regional space agenda depends, and stand to benefit from the research opportunities, training programmes and industrial partnerships it generates.</p>
<p>For TURKUNIB member universities with programmes in engineering, aerospace, telecommunications and computer science, the momentum on display in Tashkent points toward a growing set of opportunities for joint research and student involvement in one of the most ambitious scientific undertakings of the Turkic world.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/1b7c12e0-aaf9-4ede-80fb-477695fbb731.jpg" alt="Space Technologies Highlighted as a Driver of Scientific Progress at Tashkent Conference" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/8373a070-19dc-4981-a765-18cb61b2ebcb.jpg" alt="Space Technologies Highlighted as a Driver of Scientific Progress at Tashkent Conference" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-addressed-the-space-technology-conference-2026-in-tashkent">OTS Secretary General addressed the Space Technology Conference 2026 in Tashkent</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev addressed the Space Technology Conference 2026 in Tashkent on 31 March 2026, the day after the 5th Meeting of the Heads of Space Agencies of the Turkic states convened in the same city. The conference gathered experts, policymakers, industry…', '2026-03-31 09:00:00', '2026-03-31 09:00:00');
-- #15 [MEDIUM] 2026-04-09  OTS Secretary General and Rector of Ahmet Yasawi University Discuss Mo
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='02bd7943-aed4-47f4-b2d4-4b5eb0d658ed.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='higher-education'), 'TURKUNIB', 1, 1, '2026-04-09 09:00:00', '2026-04-09 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'OTS Secretary General and Rector of Ahmet Yasawi University Discuss Mobility, Joint Research and the Expanding Role of TURKUNIB', 'ots-secretary-general-and-rector-of-ahmet-yasawi-university-discuss-mobility-joint-research-and-the-expanding-role-of-turkunib', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev received Dr. Zhanar Temirbekova, Rector of the Khoja Ahmet Yasawi International Kazakh-Turkish University, at the OTS Secretariat on 9 April 2026 for talks on deepening academic cooperation across the Turkic states.</p>
<p>The discussions covered ways to strengthen collaboration among the universities of the Turkic world, enhance student and faculty mobility, and promote joint research initiatives. Particular emphasis was placed on the expanding significance of the Turkic Universities Union (TURKUNIB) and of the Orhun Exchange Programme, which the OTS described as “a key platform for deepening educational integration and fostering a shared academic space within the Turkic world.”</p>
<p>Ahmet Yasawi University, based in Turkistan, Kazakhstan, occupies a distinctive place in the region''s academic landscape as a joint Kazakh-Turkish institution with decades of experience in cross-border higher education – experience directly relevant to the common higher education space the Turkic states are now building.</p>
<p>The meeting reflects a broader pattern visible throughout 2025 and 2026: engagement between the OTS leadership and individual universities is increasingly organized around TURKUNIB and the Orhun Exchange Programme as the standing instruments of academic cooperation. For member universities, rector-level dialogues of this kind help translate the Union''s institutional reforms into concrete partnerships in mobility and research.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-received-rector-of-ahmet-yasawi-university">OTS Secretary General received Rector of Ahmet Yasawi University</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev received Dr. Zhanar Temirbekova, Rector of the Khoja Ahmet Yasawi International Kazakh-Turkish University, at the OTS Secretariat on 9 April 2026 for talks on deepening academic cooperation across the Turkic states.', '2026-04-09 09:00:00', '2026-04-09 09:00:00');
-- #24 [MEDIUM] 2026-04-27  OTS Engages OECD Skills Agenda at Istanbul Summit on Talent and Lifelo
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='83f8f03c-7d0f-4d9e-8eb2-128c67b7b7aa.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='international-cooperation'), 'TURKUNIB', 1, 1, '2026-04-27 09:00:00', '2026-04-27 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'OTS Engages OECD Skills Agenda at Istanbul Summit on Talent and Lifelong Learning', 'ots-engages-oecd-skills-agenda-at-istanbul-summit-on-talent-and-lifelong-learning', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev participated in the OECD Skills Summit 2026, held in Istanbul on 27–28 April 2026 under the theme “Unlocking Talent Across Generations.”</p>
<p>The summit''s opening was addressed by President of Türkiye Recep Tayyip Erdoğan, Minister of Labour and Social Security of Türkiye Prof. Dr. Vedat Işıkhan and OECD Secretary-General Mathias Cormann. Discussions ranged across skills development, human capital enhancement, inclusive labour markets, lifelong learning, vocational training and innovation-driven growth. The OTS Secretary General attended the official opening ceremony, took part in the tour-de-table session on skills policy development, exchanged views with the OECD Secretary-General, and presented the OTS''s institutional framework in the fields of labour, employment and social protection.</p>
<p>The Organization''s presence at a flagship OECD event reflects the growing international engagement of the Turkic cooperation framework on education-adjacent policy. Skills and human capital sit immediately downstream of higher education: the questions debated in Istanbul – how societies develop talent, retrain workforces and sustain lifelong learning – are questions in which universities are principal actors.</p>
<p>For TURKUNIB member universities, the OTS''s engagement with the OECD skills agenda signals opportunities to align regional academic cooperation with international best practice in skills and employability – dimensions increasingly important to graduates navigating the labour markets of the Turkic states and beyond.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/dbece37e-4858-47d7-a179-d0b69c9f808d.jpg" alt="OTS Engages OECD Skills Agenda at Istanbul Summit on Talent and Lifelong Learning" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/-secretary-general-of-the-organization-of-turkic-states-participated-in-the-oecd-skills-summit-2026">Secretary General of the Organization of Turkic States participated in the OECD Skills Summit 2026</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev participated in the OECD Skills Summit 2026, held in Istanbul on 27–28 April 2026 under the theme “Unlocking Talent Across Generations.”', '2026-04-27 09:00:00', '2026-04-27 09:00:00');
-- #4 [HIGH] 2026-05-15  Turkic States Leaders Focus on Artificial Intelligence and Digital Dev
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='474b2dd7-2c95-4a00-adb2-854ef30af0ce.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='innovation-technology'), 'TURKUNIB', 1, 1, '2026-05-15 09:00:00', '2026-05-15 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic States Leaders Focus on Artificial Intelligence and Digital Development at Turkistan Informal Summit', 'turkic-states-leaders-focus-on-artificial-intelligence-and-digital-development-at-turkistan-informal-summit', '<p>The Informal Summit of the Organization of Turkic States convened on 15 May 2026 in Turkistan, Kazakhstan, under the theme “Artificial Intelligence and Digital Development” – placing the technologies that are reshaping research, teaching and innovation at the very top of the Turkic cooperation agenda.</p>
<p>Hosted by President of Kazakhstan Kassym-Jomart Tokayev, the Summit brought together President of Azerbaijan Ilham Aliyev, President of the Kyrgyz Republic Sadyr Zhaparov, President of Türkiye Recep Tayyip Erdoğan, President of Uzbekistan Shavkat Mirziyoyev, President of the Turkish Republic of Northern Cyprus Tufan Erhürman and OTS Secretary General Ambassador Kubanychbek Omuraliev.</p>
<p>The leaders adopted the Turkistan Declaration together with decisions on strengthening the institutional and digital capacity of the OTS Secretariat and on the appointment of a Deputy Secretary General. Discussions centred on digital transformation and innovation, artificial intelligence and digital governance, smart infrastructure and innovation ecosystems, and sustainable economic development, framed by the long-term “Turkic World Vision-2040.” The Summit also launched the “Center of Turkic Civilization” initiative – conceived as an international-level multifunctional cultural, scientific and tourist centre integrating the heritage of the Turkic world.</p>
<p>For the academic community, the Turkistan Summit matters well beyond its diplomatic significance. By making artificial intelligence and digital development the unifying theme of the year, the Turkic states have signalled where joint projects, funding priorities and skills initiatives will concentrate – from AI research and digital governance to the innovation ecosystems in which universities play a defining role.</p>
<p>These directions align closely with the mission of TURKUNIB, whose member universities are natural partners in building the region''s digital and research capacity. The Summit''s emphasis on AI, innovation and a shared scientific infrastructure reinforces the case for deeper inter-university collaboration in precisely the fields the leaders have now identified as strategic.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/07607317-7917-41e0-9da0-01344185f0ed.jpg" alt="Turkic States Leaders Focus on Artificial Intelligence and Digital Development at Turkistan Informal Summit" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/81c2356d-3ee1-4722-88eb-88db5824f9bd.jpg" alt="Turkic States Leaders Focus on Artificial Intelligence and Digital Development at Turkistan Informal Summit" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-informal-summit-of-the-organization-of-turkic-states-convened-in-turkistan-kazakhstan">The Informal Summit of the Organization of Turkic States convened in Turkistan, Kazakhstan</a></em></p>', 'The Informal Summit of the Organization of Turkic States convened on 15 May 2026 in Turkistan, Kazakhstan, under the theme “Artificial Intelligence and Digital Development” – placing the technologies that are reshaping research, teaching and innovation at the very top of the Turkic cooperation…', '2026-05-15 09:00:00', '2026-05-15 09:00:00');
-- #10 [MEDIUM] 2026-05-21  A Century After the First Baku Turkology Congress, Scholars Gather in 
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='f27d7f3f-f732-4e0a-8ace-7252ceb3f556.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2026-05-21 09:00:00', '2026-05-21 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'A Century After the First Baku Turkology Congress, Scholars Gather in Almaty to Chart the Future of Turkic Studies', 'a-century-after-the-first-baku-turkology-congress-scholars-gather-in-almaty-to-chart-the-future-of-turkic-studies', '<p>Marking one hundred years since the First Baku Turkology Congress of 1926, the Turkic Academy and Al-Farabi Kazakh National University convened the International Conference on Turkology, “The Legacy of the First Baku Turkology Congress and the Turkic World in the 21st Century,” in Almaty on 21 May 2026.</p>
<p>Addressing the conference, OTS Secretary General Ambassador Kubanychbek Omuraliev said that the 1926 congress “laid the intellectual foundations for unity, mutual understanding and closer cooperation among Turkic peoples,” and observed that the intellectual ideas of that gathering have since evolved into today''s institutionalized cooperation spanning education, culture, science and youth initiatives. The conference addressed the preservation of the common cultural heritage of the Turkic peoples and initiatives surrounding the Common Turkic Alphabet, with the Secretary General stressing that ongoing cultural and academic initiatives continue to deepen understanding among Turkic societies.</p>
<p>The centenary conference exemplifies the model of cooperation that unites the Turkic world''s scientific institutions and its universities: a leading national university, Al-Farabi Kazakh National University, co-organizing a landmark scholarly event with the Turkic Academy, the region''s principal research institution.</p>
<p>For TURKUNIB member universities – many of which maintain departments of Turkology, philology and history – the centenary offers both a scholarly milestone and an invitation: the questions first posed in Baku a century ago, from language and alphabet to shared heritage, are today being addressed through the kind of inter-university research collaboration that TURKUNIB exists to foster.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/e8e95f83-a2cf-45f3-8dd9-aab13c87cd36.jpg" alt="A Century After the First Baku Turkology Congress, Scholars Gather in Almaty to Chart the Future of Turkic Studies" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/583758a6-ea47-4fbb-8e19-a9729eb79972.jpg" alt="A Century After the First Baku Turkology Congress, Scholars Gather in Almaty to Chart the Future of Turkic Studies" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/the-secretary-general-of-the-ots-addressed-the-international-conference-on-turkology-titled-the-legacy-of-the-first-baku-turkology-congress-and-the-turkic-world-in-the-21st-century">The Secretary General of the OTS addressed the International Conference on Turkology titled “The Legacy of the First Baku Turkology Congress and the Turkic World in the 21st Century”</a></em></p>', 'Marking one hundred years since the First Baku Turkology Congress of 1926, the Turkic Academy and Al-Farabi Kazakh National University convened the International Conference on Turkology, “The Legacy of the First Baku Turkology Congress and the Turkic World in the 21st Century,” in Almaty on 21…', '2026-05-21 09:00:00', '2026-05-21 09:00:00');
-- #26 [LOW] 2026-05-25  Young Delegates Simulate Turkic Cooperation at Model OTS 2026 in Azerb
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='f8e84187-aa67-4d9c-95ce-3ced8a624bc9.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='youth-student-affairs'), 'TURKUNIB', 1, 1, '2026-05-25 09:00:00', '2026-05-25 09:00:00');
