INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Young Delegates Simulate Turkic Cooperation at Model OTS 2026 in Azerbaijan', 'young-delegates-simulate-turkic-cooperation-at-model-ots-2026-in-azerbaijan', '<p>The international youth camp “Model Organization of Turkic States 2026” was held in Quba, Azerbaijan, from 25 to 30 May 2026, organized by Azerbaijan''s Ministry of Youth and Sports and Ministry of Justice together with the Justice Volunteers Public Union, with the OTS Secretariat represented by its Director for Projects, Murodjon Mustofoev.</p>
<p>Following the model-institution format familiar from university Model United Nations programmes, young participants from across the Turkic world assumed the roles of prime ministers, heads of ministries, civil society representatives and journalists in a large-scale simulation of the Organization of Turkic States. The programme combined panel discussions on youth innovation, governance and international negotiation with expert meetings, training sessions and the drafting of memoranda under institutional guidance, alongside cultural exhibitions, concerts and team-building activities. Senior Azerbaijani officials, including Deputy Minister of Youth and Sports Indira Hajiyeva, took part.</p>
<p>As its concluding outcome, participants jointly drafted and adopted a memorandum recommending enhanced cooperation in youth policy, education, law, digital transformation, culture and media – a youth-authored articulation of priorities that closely mirrors the formal agenda of the Turkic states.</p>
<p>Simulation formats of this kind cultivate precisely the skills universities seek to develop – negotiation, policy analysis, public speaking and cross-cultural collaboration. The camp''s outcomes reflect the growing role of structured youth engagement in Turkic cooperation, in areas closely aligned with the academic cooperation agenda that TURKUNIB advances among its member universities.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/a8b47362-d7ee-4e20-8364-06b01f515cd4.jpg" alt="Young Delegates Simulate Turkic Cooperation at Model OTS 2026 in Azerbaijan" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/4bcf11c4-a672-4bcb-ba37-d220ff2b3a3a.jpg" alt="Young Delegates Simulate Turkic Cooperation at Model OTS 2026 in Azerbaijan" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/international-youth-camp-model-organization-of-turkic-states-2026-held-in-the-city-of-quba">International Youth Camp “Model Organization of Turkic States 2026” Held in the City of Quba</a></em></p>', 'The international youth camp “Model Organization of Turkic States 2026” was held in Quba, Azerbaijan, from 25 to 30 May 2026, organized by Azerbaijan''s Ministry of Youth and Sports and Ministry of Justice together with the Justice Volunteers Public Union, with the OTS Secretariat represented by…', '2026-05-25 09:00:00', '2026-05-25 09:00:00');
-- #1 [HIGH] 2026-06-08  Education Ministers of the Turkic States Endorse Permanent TURKUNIB Se
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='8de61621-e6ea-4f0c-bc9f-57418560ff95.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='higher-education'), 'TURKUNIB', 1, 1, '2026-06-08 09:00:00', '2026-06-08 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Education Ministers of the Turkic States Endorse Permanent TURKUNIB Secretariat and Dedicated Fund for the Orhun Exchange Programme', 'education-ministers-of-the-turkic-states-endorse-permanent-turkunib-secretariat-and-dedicated-fund-for-the-orhun-exchange-programme', '<p>The 9th Meeting of the Ministers of Education of the Organization of Turkic States (OTS), held on 8 June 2026 in Turkistan, Kazakhstan, delivered some of the most consequential decisions for higher education cooperation in the Turkic world in recent years. The meeting, attended by the Ministers of Education of the OTS Member States and OTS Secretary General Ambassador Kubanychbek Omuraliev, concluded with the adoption of a joint Communique.</p>
<p>Of particular significance for the university community, the ministers noted that membership of the Turkic Universities Union (TURKUNIB) has grown to 170 universities, and endorsed two landmark institutional steps: the establishment of a Permanent TURKUNIB Secretariat and the creation of a Dedicated Programme Fund for the Orhun Exchange Programme. The OTS has allocated one million US dollars to support the development of the exchange programme, which enables student and staff mobility among universities of the Turkic states.</p>
<p>The ministerial meeting also advanced a broad package of initiatives designed to build a common higher education space across the Turkic world. These include the establishment of a Turkic World Higher Education Data Bank; the creation of a Turkic World Association for Quality Assurance in Higher Education (TWAQA); diploma certification and equivalency mechanisms for TURKUNIB member universities; the establishment of a Turkic Universities League; expanded student and teacher exchange programmes together with a “sister school” practice; a Turkic States Education Information Network; and an Education Cooperation Working Group to carry the agenda forward.</p>
<p>On the margins of the meeting, the OTS Secretary General held bilateral consultations with the Minister of Science and Higher Education of Kazakhstan, Sayasat Nurbek, focusing on the practical steps required to establish the Permanent TURKUNIB Secretariat and the mobility fund, and with the Minister of Science and Education of Azerbaijan, Emin Amrullayev, on cooperation in education, science and academic mobility.</p>
<p>For TURKUNIB and its member universities, the Turkistan decisions represent a decisive step from cooperation to institutionalization. A permanent secretariat, a funded mobility programme, a shared quality assurance framework and recognized diploma equivalency mechanisms together form the backbone of an emerging Turkic World Higher Education Area – an agenda in which TURKUNIB member universities are both the principal contributors and the principal beneficiaries.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/fe184739-4b09-4122-9aac-006beba3b6af.jpg" alt="Education Ministers of the Turkic States Endorse Permanent TURKUNIB Secretariat and Dedicated Fund for the Orhun Exchange Programme" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/1409acd7-7707-459f-8888-f284ec6d1d73.jpg" alt="Education Ministers of the Turkic States Endorse Permanent TURKUNIB Secretariat and Dedicated Fund for the Orhun Exchange Programme" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/9th-meeting-of-ministers-of-education-of-the-ots-was-held-in-turkistan">9th Meeting of Ministers of Education of the OTS was held in Turkistan</a></em></p>', 'The 9th Meeting of the Ministers of Education of the Organization of Turkic States (OTS), held on 8 June 2026 in Turkistan, Kazakhstan, delivered some of the most consequential decisions for higher education cooperation in the Turkic world in recent years. The meeting, attended by the Ministers…', '2026-06-08 09:00:00', '2026-06-08 09:00:00');
-- #9 [MEDIUM] 2026-06-08  Turkic Academy Scientific Council Advances the “Common History of Turk
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='2121de48-8c23-469c-a7eb-0d7e1efea828.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='science-research'), 'TURKUNIB', 1, 1, '2026-06-08 09:00:00', '2026-06-08 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Turkic Academy Scientific Council Advances the “Common History of Turkic Countries” Project', 'turkic-academy-scientific-council-advances-the-common-history-of-turkic-countries-project', '<p>The 8th Meeting of the Scientific Council of the Turkic Academy was held in Turkistan, Kazakhstan, on 8 June 2026, bringing together delegations from Azerbaijan, Kazakhstan, Kyrgyzstan, Türkiye and Uzbekistan with the participation of OTS Secretary General Ambassador Kubanychbek Omuraliev. The Council convened on the same day as the 9th Meeting of the OTS Ministers of Education, underscoring the close connection between the scientific and educational tracks of Turkic cooperation.</p>
<p>The Council reviewed the Turkic Academy''s strategic priorities and future activities. A central item on the agenda was the implementation of the “Common History of Turkic Countries” project – a joint scholarly undertaking that the Secretary General described as “constructive, inclusive, and professional,” encouraging the member states to lend it their full support. In his remarks, Ambassador Omuraliev emphasized the importance of strengthening scientific, educational and cultural cooperation across the Turkic world and of building a shared historical consciousness grounded in rigorous research.</p>
<p>The Turkic Academy, headquartered in Astana, serves as the principal scientific institution of the Turkic cooperation framework, coordinating research on the history, languages and cultural heritage of the Turkic peoples and engaging historians, linguists and social scientists from universities across the region.</p>
<p>For the university community of the Turkic world, the Council''s agenda is a reminder that joint scholarship – exemplified by the Common History project – depends on the participation of university researchers in every member state. The initiative reflects the same spirit of academic cooperation that TURKUNIB promotes among its member universities, and offers natural points of connection for historians and humanities faculties across the Union.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/ccdec57c-7748-4139-a35f-d90ce7ae28a7.jpg" alt="Turkic Academy Scientific Council Advances the “Common History of Turkic Countries” Project" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/8cb3d4b6-fc04-4686-b7e3-1f2f8732bdf4.jpg" alt="Turkic Academy Scientific Council Advances the “Common History of Turkic Countries” Project" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-participated-in-the-meeting-of-the-scientific-council-of-the-turkic-academy-held-in-turkistan">OTS Secretary General participated in the Meeting of the Scientific Council of the Turkic Academy held in Turkistan</a></em></p>', 'The 8th Meeting of the Scientific Council of the Turkic Academy was held in Turkistan, Kazakhstan, on 8 June 2026, bringing together delegations from Azerbaijan, Kazakhstan, Kyrgyzstan, Türkiye and Uzbekistan with the participation of OTS Secretary General Ambassador Kubanychbek Omuraliev. The…', '2026-06-08 09:00:00', '2026-06-08 09:00:00');
-- #17 [MEDIUM] 2026-07-06  Young Minds of the Turkic World Gather in Istanbul for the 3rd Turkic 
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='2702692b-781b-4578-a28f-c0e44aea1a43.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='youth-student-affairs'), 'TURKUNIB', 1, 1, '2026-07-06 09:00:00', '2026-07-06 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Young Minds of the Turkic World Gather in Istanbul for the 3rd Turkic World Summer Forum', 'young-minds-of-the-turkic-world-gather-in-istanbul-for-the-3rd-turkic-world-summer-forum', '<p>The 3rd Turkic World Summer Forum convened in Istanbul from 6 to 15 July 2026 under the title “The Future of the Turkic World,” hosted by Ibn Haldun University. At the outset of the programme, OTS Secretary General Ambassador Kubanychbek Omuraliev welcomed the forum''s young participants at the OTS Secretariat.</p>
<p>Now in its third edition, the Summer Forum has established itself as a recurring platform bringing together young people from across the Turkic states for ten days of academic exchange. The programme is dedicated to dialogue, academic cooperation and the strengthening of bonds among the youth of the Turkic world – combining scholarly engagement with the personal networks on which long-term regional cooperation is built. The OTS lists the forum within its education activities, and its Secretary General''s personal engagement with participants underscores the importance the Organization attaches to the format.</p>
<p>The forum belongs to a growing family of youth-focused academic initiatives across the Turkic world – from the Turkic World Summer School, whose 2025 edition hosted a dedicated workshop on the Orhun Process and TURKUNIB, to model-OTS simulations and student exchange programmes – that together cultivate a generation of scholars and professionals at home in the wider region.</p>
<p>For TURKUNIB member universities, initiatives of this kind complement institutional cooperation with people-to-people academic ties. The forum''s host, Ibn Haldun University, illustrates the role individual universities can play in convening the youth of the Turkic world – a model open to institutions across the Union.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/39d02b44-7ee7-4a8f-9f44-f58a076da4f0.jpg" alt="Young Minds of the Turkic World Gather in Istanbul for the 3rd Turkic World Summer Forum" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/1b08cc2a-3ced-4976-91b6-fe10e3f5b3f5.jpg" alt="Young Minds of the Turkic World Gather in Istanbul for the 3rd Turkic World Summer Forum" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-welcomed-participants-of-the-3rd-turkic-world-summer-forum">OTS Secretary General welcomed participants of the 3rd Turkic World Summer Forum</a></em></p>', 'The 3rd Turkic World Summer Forum convened in Istanbul from 6 to 15 July 2026 under the title “The Future of the Turkic World,” hosted by Ibn Haldun University. At the outset of the programme, OTS Secretary General Ambassador Kubanychbek Omuraliev welcomed the forum''s young participants at the…', '2026-07-06 09:00:00', '2026-07-06 09:00:00');
-- #27 [LOW] 2026-07-10  OTS Opens Internship Programme, Offering Young People of the Turkic Wo
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='b3a5c43a-4a0a-4f53-a158-081aaca43789.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='youth-student-affairs'), 'TURKUNIB', 1, 1, '2026-07-10 09:00:00', '2026-07-10 09:00:00');
