INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'OTS Opens Internship Programme, Offering Young People of the Turkic World Experience in Multilateral Diplomacy', 'ots-opens-internship-programme-offering-young-people-of-the-turkic-world-experience-in-multilateral-diplomacy', '<p>The Organization of Turkic States opened applications for its Internship Programme on 10 July 2026, inviting young people from across the Turkic world to gain first-hand experience of multilateral cooperation at the OTS Secretariat. The selection concluded with the announcement of the final list of successful candidates on 18 August 2026.</p>
<p>The internship programme, which the OTS has run in successive cohorts – with multiple groups completing their terms during 2025 – has become a regular channel through which students and recent graduates engage directly with the work of the Organization, from its education and youth portfolios to its economic, cultural and technological cooperation agendas.</p>
<p>For universities, programmes of this kind are a practical complement to classroom education in international relations, law, economics and area studies. They give students of the Turkic states professional exposure to regional diplomacy and build a cadre of young professionals who understand the institutions of Turkic cooperation from within – including the frameworks, such as the Orhun Exchange Programme and TURKUNIB, through which the academic dimension of that cooperation is organized.</p>
<p>TURKUNIB member universities may wish to draw such opportunities to the attention of their students and graduates through their career services and international offices, as recurring openings connected to the wider ecosystem of Turkic cooperation in which the Union operates.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/organization-of-turkic-states-launches-applications-for-the-ots-internship-programme">Organization of Turkic States Launches Applications for the OTS Internship Programme</a></em></p>', 'The Organization of Turkic States opened applications for its Internship Programme on 10 July 2026, inviting young people from across the Turkic world to gain first-hand experience of multilateral cooperation at the OTS Secretariat. The selection concluded with the announcement of the final list…', '2026-07-10 09:00:00', '2026-07-10 09:00:00');
-- #16 [MEDIUM] 2026-07-30  Artificial Intelligence, Digital Transformation and the OTS Satellite 
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='7a4ea1ee-c74b-4754-aa88-c7883b922bf2.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='innovation-technology'), 'TURKUNIB', 1, 1, '2026-07-30 09:00:00', '2026-07-30 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Artificial Intelligence, Digital Transformation and the OTS Satellite on the Agenda in Astana', 'artificial-intelligence-digital-transformation-and-the-ots-satellite-on-the-agenda-in-astana', '<p>OTS Secretary General Ambassador Kubanychbek Omuraliev met in Astana on 30 July 2026 with Zhaslan Madiyev, Deputy Prime Minister and Minister of Artificial Intelligence of the Republic of Kazakhstan – a meeting emblematic of how central advanced technologies have become to Turkic cooperation.</p>
<p>The discussions focused on artificial intelligence and digital transformation, described as key drivers of sustainable economic development and regional competitiveness, alongside emerging technological trends. The two officials also reviewed the OTS satellite project, including questions surrounding its finalization and launch – the 12U OTS-SAT CubeSat being the first jointly developed satellite of the Turkic states.</p>
<p>Both sides reaffirmed their commitment to strengthening collaboration in artificial intelligence and digital transformation through practical projects, institutional cooperation and regular dialogue within the OTS framework. The meeting followed the Turkistan Informal Summit of May 2026, which was dedicated to the theme of artificial intelligence and digital development, and the Shymkent panel of March 2026 at which the member states committed to joint hackathons and competitions.</p>
<p>The consolidation of AI as a standing pillar of Turkic cooperation carries clear implications for higher education: research capacity, talent development and digital skills are university domains. As governments organize themselves around the AI agenda – Kazakhstan now maintaining a dedicated ministry – universities of the Turkic world, including TURKUNIB members, are positioned to serve as the region''s laboratories and training grounds for the technologies its leaders have prioritized.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/52bc2e50-ad02-492b-9877-c468c94957fe.jpg" alt="Artificial Intelligence, Digital Transformation and the OTS Satellite on the Agenda in Astana" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/-secretary-general-of-the-ots-met-with-the-deputy-prime-minister-and-minister-of-artificial-intelligence-of-the-republic-of-kazakhstan">Secretary General of the OTS met with the Deputy Prime Minister and Minister of Artificial Intelligence of the Republic of Kazakhstan</a></em></p>', 'OTS Secretary General Ambassador Kubanychbek Omuraliev met in Astana on 30 July 2026 with Zhaslan Madiyev, Deputy Prime Minister and Minister of Artificial Intelligence of the Republic of Kazakhstan – a meeting emblematic of how central advanced technologies have become to Turkic cooperation.', '2026-07-30 09:00:00', '2026-07-30 09:00:00');
-- #18 [MEDIUM] 2026-08-23  Students from Six Turkic Countries Complete Space Camp in İzmir as STE
INSERT INTO news (image_id, category_id, author_name, enabled, author_id, created_at, updated_at) VALUES ((SELECT id FROM images WHERE image_file_name='545a60ab-42d3-417e-b7ae-eb0925b219d5.jpg'), (SELECT c.id FROM news_categories c JOIN news_categories_i18n ci ON ci.category_id=c.id AND ci.locale='EN' WHERE ci.slug='youth-student-affairs'), 'TURKUNIB', 1, 1, '2026-08-23 09:00:00', '2026-08-23 09:00:00');
SET @nid = LAST_INSERT_ID();
INSERT INTO news_i18n (news_id, locale, title, slug, content, description, created_at, updated_at) VALUES (@nid, 'EN', 'Students from Six Turkic Countries Complete Space Camp in İzmir as STEM Cooperation Expands', 'students-from-six-turkic-countries-complete-space-camp-in-izmir-as-stem-cooperation-expands', '<p>Sixty-five students and twelve teachers from Azerbaijan, Kazakhstan, the Kyrgyz Republic, Türkiye, Uzbekistan and the Turkish Republic of Northern Cyprus completed the 4th TUA Space Explorers Türkiye Space Camp Program, held from 23 to 29 August 2026 at ESBAŞ Space Camp Türkiye in İzmir.</p>
<p>The week-long programme, organized by the Turkish Space Agency (TUA) in partnership with ESBAŞ and Space Camp Türkiye, immersed participants in space science and technology education. Addressing the certificate ceremony, OTS Secretary General Ambassador Kubanychbek Omuraliev commended the organizers for supporting scientific cooperation among the youth of the Turkic world and encouraged the students to pursue careers in science, technology, engineering and space exploration, describing them as potential future leaders of the region''s development.</p>
<p>The Secretary General invoked the Turkic world''s rich astronomical and scientific heritage and pointed to the Joint Cube Satellite Project – the 12U OTS-SAT, developed jointly by the space agencies of the Turkic states – as proof of what the region can achieve in advanced technologies through collaboration.</p>
<p>Programmes such as the Space Explorers camp form the early links of a talent chain that runs directly into higher education: the students introduced to space science in İzmir are the future applicants to the engineering, physics and computer science faculties of the region''s universities. For TURKUNIB member universities, the expanding STEM youth agenda of the Turkic states – space camps, academies and competitions – both reflects and feeds the growing scientific ambition of the region they serve.</p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/1accd781-65c2-48c7-a8ad-a5f55095205c.jpg" alt="Students from Six Turkic Countries Complete Space Camp in İzmir as STEM Cooperation Expands" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><img src="/uploads/images/11092026/4d81aa91-b336-4a3b-827d-c240b71f29c9.jpg" alt="Students from Six Turkic Countries Complete Space Camp in İzmir as STEM Cooperation Expands" style="max-width:100%;height:auto;"></p>
<p><small>Photo: Organization of Turkic States (turkicstates.org)</small></p>
<p><em>Based on official OTS reporting: <a href="https://turkicstates.org/en/news/ots-secretary-general-addressed-the-4th-tua-space-explorers-turkiye-space-camp-program-in-izmir">OTS Secretary General addressed the 4th TUA Space Explorers Türkiye Space Camp Program in İzmir</a></em></p>', 'Sixty-five students and twelve teachers from Azerbaijan, Kazakhstan, the Kyrgyz Republic, Türkiye, Uzbekistan and the Turkish Republic of Northern Cyprus completed the 4th TUA Space Explorers Türkiye Space Camp Program, held from 23 to 29 August 2026 at ESBAŞ Space Camp Türkiye in İzmir.', '2026-08-23 09:00:00', '2026-08-23 09:00:00');
COMMIT;
